from httpbin.core import app
client = app.test_client()

# Set a large number of cookies
for i in range(1, 101):
    client.get(f'/cookies/set/cookie{i}/value{i}')

# Get cookies
response = client.get('/cookies')
assert response.status_code == 200
expected_cookies = {f'cookie{i}': f'value{i}' for i in range(1, 101)}
assert response.json == {'cookies': expected_cookies}
